import * as T from './assets/three.module.js';
export function sceneNavigation(root,camera,{distance=15,pitch=.3,yaw=.4,targetY=0}={}){
 let target=new T.Vector3(0,targetY,0),freePosition=new T.Vector3(),distanceGoal=distance,yawGoal=yaw,pitchGoal=pitch,free=false,last={x:0,y:0},keys=new Set(),pointers=new Map(),pinch=0;const initial={distance,pitch,yaw};
 root.addEventListener('pointerdown',e=>{root.focus();pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});last={x:e.clientX,y:e.clientY};root.setPointerCapture(e.pointerId);if(pointers.size===2){const p=[...pointers.values()];pinch=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)}});
 root.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const p=[...pointers.values()],d=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);distanceGoal=Math.max(.8,Math.min(200,distanceGoal*Math.exp((pinch-d)*.006)));pinch=d;}else{const dx=e.clientX-last.x,dy=e.clientY-last.y;if(e.shiftKey||e.buttons===2){const right=new T.Vector3().setFromMatrixColumn(camera.matrix,0),up=new T.Vector3().setFromMatrixColumn(camera.matrix,1);target.addScaledVector(right,-dx*distance*.0015).addScaledVector(up,dy*distance*.0015);}else{yawGoal-=dx*.005;pitchGoal=Math.max(-1.5,Math.min(1.5,pitchGoal+dy*.005));}}last={x:e.clientX,y:e.clientY}});
 const release=e=>{pointers.delete(e.pointerId);if(pointers.size===1)last=[...pointers.values()][0]};['pointerup','pointercancel','lostpointercapture'].forEach(k=>root.addEventListener(k,release));root.addEventListener('contextmenu',e=>e.preventDefault());root.addEventListener('wheel',e=>{if(document.activeElement===root||e.ctrlKey){e.preventDefault();distanceGoal=Math.max(.8,Math.min(200,distanceGoal*Math.exp(e.deltaY*.0015)))}},{passive:false});
 root.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','+','=','-','0','w','a','s','d','q','e','W','A','S','D','Q','E'].includes(e.key)){e.preventDefault();keys.add(e.key.toLowerCase());if(e.key==='+'||e.key==='=')distanceGoal=Math.max(.8,distanceGoal*.8);if(e.key==='-')distanceGoal=Math.min(200,distanceGoal/.8);if(e.key==='0')reset()}});root.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));root.addEventListener('blur',()=>keys.clear());
 function reset(d=initial.distance){target.set(0,targetY,0);freePosition.set(Math.sin(initial.yaw)*Math.cos(initial.pitch)*d,Math.sin(initial.pitch)*d,Math.cos(initial.yaw)*Math.cos(initial.pitch)*d);distanceGoal=d;yawGoal=initial.yaw;pitchGoal=initial.pitch;keys.clear()}
 function update(dt,motion=true){const damp=motion?1-Math.exp(-dt*10):1;distance+=(distanceGoal-distance)*damp;yaw+=(yawGoal-yaw)*damp;pitch+=(pitchGoal-pitch)*damp;if(keys.has('arrowleft'))yawGoal-=dt;if(keys.has('arrowright'))yawGoal+=dt;if(keys.has('arrowup'))pitchGoal=Math.min(1.5,pitchGoal+dt);if(keys.has('arrowdown'))pitchGoal=Math.max(-1.5,pitchGoal-dt);if(free){const forward=new T.Vector3(-Math.sin(yaw)*Math.cos(pitch),-Math.sin(pitch),-Math.cos(yaw)*Math.cos(pitch)),right=new T.Vector3(Math.cos(yaw),0,-Math.sin(yaw)),step=Math.max(2,distance*.5)*dt;freePosition.addScaledVector(forward,((keys.has('w')?1:0)-(keys.has('s')?1:0))*step).addScaledVector(right,((keys.has('d')?1:0)-(keys.has('a')?1:0))*step);freePosition.y+=((keys.has('e')?1:0)-(keys.has('q')?1:0))*step;camera.position.copy(freePosition);camera.lookAt(freePosition.clone().add(forward));return;}camera.position.set(target.x+Math.sin(yaw)*Math.cos(pitch)*distance,target.y+Math.sin(pitch)*distance,target.z+Math.cos(yaw)*Math.cos(pitch)*distance);camera.lookAt(target)}
 return {update,reset,get moving(){return Math.abs(distanceGoal-distance)+Math.abs(yawGoal-yaw)+Math.abs(pitchGoal-pitch)>.0001||keys.size>0}, setPose({yaw:nextYaw=yawGoal,pitch:nextPitch=pitchGoal,distance:nextDistance=distanceGoal,target:nextTarget}={}){yawGoal=nextYaw;pitchGoal=nextPitch;distanceGoal=nextDistance;if(nextTarget)target.set(nextTarget.x,nextTarget.y,nextTarget.z)}, setTarget(x,y,z){target.set(x,y,z)}, get free(){return free},set free(v){if(v&&!free)freePosition.copy(camera.position);if(!v&&free)target.copy(freePosition).add(new T.Vector3(-Math.sin(yaw)*Math.cos(pitch),-Math.sin(pitch),-Math.cos(yaw)*Math.cos(pitch)).multiplyScalar(distance));free=v}};
}
